questionvariables.text:
/* Dimensions (cm) */
R: rand(6)+6;      /* Lower radius: 6–11 cm */
r: rand(R-2)+2;    /* Upper radius: 2,...,R-1 cm */
h: rand(7)+4;      /* Height: 4–10 cm */

/* Slant height */
s: sqrt(h^2+(R-r)^2);
/*my pivalue*/
my_pi: 3.142;
/* Correct answer */
ta: expand(my_pi*(R^2+r^2+(R+r)*s));

/* Display value of slant height (2 d.p.) */
sdisp: float(round(100*s)/100);

/* Common mistakes*/                                               

/* M1: Uses the vertical height instead of the slant height */
mistake1: expand(my_pi*(R^2+r^2+(R+r)*h));

/* M2: Uses (R-r) instead of (R+r) in the lateral area formula */
mistake2: expand(my_pi*(R^2+r^2+(R-r)*l));

/* M3: Incorrect application of Pythagoras for the slant height */
l_wrong: sqrt(h^2+R^2-r^2);
mistake3: expand(my_pi*(R^2+r^2+(R+r)*l_wrong));
